import { pieceUrl, wearUrl, type LookSlot } from '../../charter/look.js'
import { BUILT_IN, type PieceEntry } from '../pieces.js'
import type { ItemChannel, ItemSlot, Knob } from './item.js'
import { BUILT_IN_ITEMS } from './library.gen.js'

/**
 * The wardrobe library: every item a hero can wear, built in or generated by a player. Built-in surface items come
 * from tools/blender/wardrobe.py through the fit pipeline (library.gen.ts); built-in rigid pieces from
 * tools/blender/pieces.py (src/kit/pieces.ts). Both are free for everyone, as is anything a player generated once it
 * joins the shared library.
 */

/** A built-in surface item as the fit pipeline lists it. */
export interface BuiltInItem {
  id: string
  name: string
  slot: ItemSlot
  /** Words a prompt may use for it, longest first where it matters. */
  tags: readonly string[]
  channels: readonly ItemChannel[]
  knobs: readonly Knob[]
  tris: number
}

export interface LibraryEntry {
  id: string
  name: string
  slot: ItemSlot
  tags: readonly string[]
  url: string
  thumb: string
  source: 'built-in' | 'community'
  /** Up to four channels; a rigid piece has one when its primary material can take a colour. */
  channels: readonly ItemChannel[]
  knobs: readonly Knob[]
  /** How many saved heroes wear it (community items). */
  uses?: number
}

const PIECE_SLOT: Record<PieceEntry['kind'], ItemSlot> = { head: 'head', face: 'face', hand: 'hand', offhand: 'offhand', back: 'back' }

export const LIBRARY: readonly LibraryEntry[] = [
  ...BUILT_IN_ITEMS.map((i) => ({ ...i, url: wearUrl(i.id), thumb: `/kit/wear/${i.id}.webp`, source: 'built-in' as const })),
  ...BUILT_IN.map((p) => ({
    id: p.id,
    name: p.name,
    slot: PIECE_SLOT[p.kind],
    tags: p.tags,
    url: pieceUrl(p.id),
    thumb: p.thumb,
    source: 'built-in' as const,
    channels: p.tint ? [{ name: 'primary', color: p.tint, finish: 'cotton' as const }] : [],
    knobs: [],
  })),
]

const byId = new Map(LIBRARY.map((e) => [e.id, e]))

export function libraryItem(id: string): LibraryEntry | undefined {
  return byId.get(id)
}

/** Which look slots an item of this kind can be worn in: hand pieces in either hand, an off-hand piece in the left. */
export function slotsFor(slot: ItemSlot): LookSlot[] {
  if (slot === 'hand') return ['hand_r', 'hand_l']
  if (slot === 'offhand') return ['hand_l']
  return [slot]
}
